suppressPackageStartupMessages({library(data.table);library(ggplot2)})
s<-fread('outputs/final/standardized_conditional_survival_ASC_target.csv');s[,outcome:=factor(outcome,levels=c('os_event','css_event'),labels=c('Overall survival','Cancer-specific survival'))];s[,landmark:=factor(landmark_month,levels=c(0,12,24),labels=c('Diagnosis\nn = 325','12 months\nn = 184','24 months\nn = 141'))]
p<-ggplot(s,aes(landmark,100*difference))+geom_hline(yintercept=0,linetype=2,colour='grey55',linewidth=.4)+geom_errorbar(aes(ymin=100*lower95,ymax=100*upper95),width=.12,colour='#305979',linewidth=.7)+geom_point(size=2.8,colour='#305979')+facet_wrap(~outcome,nrow=1)+labs(x='Time already survived (ASC target population)',y='36-month survival difference\nASC minus adenocarcinoma NOS (percentage points)')+theme_classic(base_size=11,base_family='Arial')+theme(strip.background=element_blank(),strip.text=element_text(face='bold'),axis.text=element_text(colour='black'),panel.spacing=grid::unit(1,'cm'))+scale_y_continuous(breaks=seq(-15,15,5),limits=c(-13,13))
ggsave('outputs/final/Figure2_standardized_conditional_survival.png',p,width=7.3,height=3.8,dpi=600,bg='white');ggsave('outputs/final/Figure2_standardized_conditional_survival.tiff',p,width=7.3,height=3.8,dpi=600,compression='lzw',bg='white')
fwrite(s,'outputs/final/Figure2_data.csv')
b<-readRDS('work/revision_bootstrap.rds');cat('Successful bootstrap replicates:',sum(complete.cases(b$replicates)),'\n');cat('Bootstrap warnings:',length(unlist(b$warnings)),'\n')
